using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HeartFragmentOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/HeartFragment Omen Data")]
public class HeartFragmentOmenData : OmenData
{
	[Header("Freeze Debt Omen")]
	[SerializeField]
	private StarAbilityReference starAbilityReference;

	[SerializeField]
	private DevotionOrbStarAbility devotionOrbStarAbility;

	[SerializeField]
	private Effect hypersensitiveAuraEffect;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.HeartFragmentMovingAction = delegate
		{
			UnitEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>();
			if (starAbilityReference.Value == devotionOrbStarAbility)
			{
				component.RemoveEffect(hypersensitiveAuraEffect);
			}
			else if (!component.IsEffectActive(hypersensitiveAuraEffect, activateFeedback: false))
			{
				ActivateOmen();
			}
		};
		ReferenceSingleton<OrionOmensHandler>.Instance.HeartFragmentStartOfBattleAction = delegate
		{
			if (starAbilityReference.Value != devotionOrbStarAbility)
			{
				omenInstance.ActivateOmenFeedback();
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
				{
					ActivateOmen();
				});
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.HeartFragmentMovingAction = null;
		ReferenceSingleton<OrionOmensHandler>.Instance.HeartFragmentStartOfBattleAction = null;
	}
}
